#[command(name = "ulidgen", version, about)]
struct Cli {
    /// print N consecutive ULID
    #[arg(short = 'n', long = "count", default_value_t = 1)]
    count: u64,

    /// read lines from standard input, and prefix each line with a ULID
    #[arg(short = 't', long = "tag")]
    tag: bool,
}

